u679c\\u6587\\u4ef6\\u3001\\u4e0d\\u4f9d\\u8d56\\u4efb\\u4f55\\u5177\\u4f53\\u6570\\u636e\\u96c6\\u3001\\u4e0d\\u5047\\u5b9a\\u76ee\\u6807\\u673a\\u5668\\u7684\\u5f53\\u524d Python \\u73af\\u5883\\u5df2\\u5177\\u5907\\u4f9d\\u8d56\\u3002\\u540e\\u7eed\\u6267\\u884c\\u4eba\\u5458\\u5e94\\u80fd\\u5728\\u8131\\u673a\\u73af\\u5883\\u4e0b\\u6309\\u672c\\u6587\\u4ef6\\u6307\\u5f15\\u4e00\\u6b21\\u6027\\u590d\\u73b0\\u51fa\\u6d41\\u7a0b\\u4e0e\\u4ea7\\u51fa\\u3002\\n\\n## 2. \\u8f93\\u5165\\u6570\\u636e\\u5951\\u7ea6\\n\\n\\u8f93\\u5165\\u4ee5\\\"\\u53c2\\u6570\\u5316\\u5951\\u7ea6\\\"\\u5f62\\u5f0f\\u5217\\u51fa\\uff0c\\u5bf9\\u5177\\u4f53\\u6570\\u636e\\u96c6**\\u4e0d\\u9501\\u5b9a**\\uff1b\\u516c\\u5f00\\u6765\\u6e90\\uff08ChEMBL\\u3001PubChem\\uff09\\u53ef\\u4f5c\\u9644\\u5f55\\u793a\\u4f8b\\u4f46**\\u4e0d**\\u4f5c\\u524d\\u7f6e\\u6761\\u4ef6\\u3002\\n\\n| \\u8f93\\u5165\\u5f62\\u5f0f | \\u5fc5\\u5907\\u5b57\\u6bb5 | \\u53ef\\u9009\\u5b57\\u6bb5 | \\u89e3\\u6790\\u5931\\u8d25\\u56de\\u9000 |\\n|---|---|---|---|\\n| `.smi` / `.txt` | \\u6bcf\\u884c\\u4e00\\u6761 SMILES\\uff1b\\u53ef\\u9009\\u7a7a\\u683c\\u5206\\u9694 `<id>` | `<name>` | \\u6574\\u884c\\u5199\\u5165 `parse_failures.log` |\\n| `.csv` / `.tsv` | `smiles` | `id`\\u3001`name`\\u3001`source_index`\\u3001\\u5176\\u4f59\\u5217\\u900f\\u4f20 | \\u7f3a\\u5217\\u89e6\\u53d1\\u53c2\\u6570\\u6821\\u9a8c\\u9519\\u8bef\\u5e76\\u7ec8\\u6b62 |\\n| `.sdf` | \\u591a\\u5206\\u5b50\\u5757 | \\u8fde\\u63a5\\u8868\\u6761\\u76ee | \\u5757\\u7ea7\\u5931\\u8d25\\u88ab\\u8bb0\\u5165\\u65e5\\u5fd7 |\\n| InChI \\u884c\\u5f0f | \\u6bcf\\u884c\\u4e00\\u6761 InChI\\uff0c\\u9700 `--inchi-mode true` | \\u2014 | \\u89e3\\u6790\\u5931\\u8d25\\u6309\\u884c\\u8bb0\\u5f55 |\\n\\n\\u6e05\\u6d17\\u6d41\\u6c34\\u7ebf\\uff08\\u6309\\u9632\\u9519\\u4e3a\\u5148\\u7684\\u6b21\\u5e8f\\uff09\\uff1a\\n\\n1. \\u4f7f\\u7528 `Chem.MolFromSmiles` / `Chem.MolFromMolBlock` / `Chem.MolFromInchi` \\u89e3\\u6790\\u3002\\n2. `rdMolStandardize.Uncharger` \\u4e2d